const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed={phase:'Resolve imports',events:[{title:'Evaluation E-017 passed',notes:'Example · 42 integration checks passed for CH-024. Decision D-008 → implementation CH-024 → evaluation E-017.',time:'Example · cycle 023'},{title:'CH-024 implemented · isolate import adapters',notes:'Example · Local LLM implemented ticket AB-108 following decision D-008.',time:'Example · cycle 023'},{title:'D-008 · preserve domain boundaries',notes:'Example · Human accepted adapter strategy. Linked to AB-108 and CH-024.',time:'Example · cycle 023'}],decisions:{},proposals:{},tickets:[['AB-112','Resolve lifecycle adapter conflict','Merge review','External loop','M-03'],['AB-111','Map foreign project capabilities','In progress','Local LLM','M-03'],['AB-110','Evaluate import compatibility','Proposed','External loop','M-03'],['AB-108','Isolate import adapters','Implemented','Local LLM','M-02']],changes:[['CH-027','Bridge import lifecycle through an adapter','Proposed','AB-112'],['CH-026','Map capabilities across domain boundaries','In progress','AB-111'],['CH-024','Isolate import adapters','Implemented','AB-108']]};let state;try{state=JSON.parse(localStorage.getItem('autobuilder-observatory-v1'))||structuredClone(seed)}catch{state=structuredClone(seed)}let selected=0,view='overview',modalMode='event';
const files=[{name:'ImportCoordinator.java',path:'src/main/java/imports/ImportCoordinator.java',kind:'Lifecycle mismatch',a:'// Target · peaches\n@Service\nclass ImportCoordinator {\n  void evolve(Cycle cycle) {\n    pipeline.run(cycle);\n  }\n}',b:'// Imported · apples\nclass ImportCoordinator {\n  void execute(Job job) {\n    executor.submit(job);\n  }\n}',options:[['Preserve + adapt','Retain the Spring-managed cycle lifecycle. Translate imported jobs through an adapter.','Lower integration risk · adds a boundary layer'],['Adopt imported lifecycle','Replace the cycle entry point with the imported executor and update callers.','Broader change · requires lifecycle regression checks']]},{name:'application.yml',path:'src/main/resources/application.yml',kind:'Configuration collision',a:'spring:\n  application:\n    name: autobuilder\nimports:\n  enabled: true',b:'spring:\n  application:\n    name: apple-engine\nexecutor:\n  parallelism: 4',options:[['Namespace imported settings','Keep Autobuilder application identity; move foreign settings under imports.apple.','Explicit mapping · avoids configuration collisions'],['Merge shared settings','Consolidate keys and migrate configuration consumers.','Less duplication · larger validation scope']]},{name:'CapabilityRegistry.java',path:'src/main/java/capabilities/CapabilityRegistry.java',kind:'Semantic mismatch',a:'interface CapabilityRegistry {\n  Capability resolve(Signal signal);\n}',b:'interface CapabilityRegistry {\n  Handler resolve(String jobType);\n}',options:[['Introduce a translator','Map imported job types to capabilities, preserving both contracts.','Preserves meaning · requires mapping coverage'],['Unify the contract','Evolve both registries into a shared capability abstraction.','Architectural change · requires caller migration']]}];
const views=[['overview','◫','Overview'],['roadmap','⌁','Roadmap'],['tickets','▤','Tickets'],['agents','⬡','Agent roles'],['changes','↗','Changes'],['merges','⑂','Merge workbench'],['history','◷','Decision history'],['evaluations','✓','Evaluations'],['signals','≋','Signals']];
function persist(){localStorage.setItem('autobuilder-observatory-v1',JSON.stringify(state))}function badge(t,c=''){return `<span class="badge ${c}">${esc(t)}</span>`}function panel(title,body,link=''){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${link}</div>${body}</section>`}function goLink(v,t){return `<a class="link" href="#${v}">${t} ↗</a>`}function events(){return `<div class="timeline">${state.events.map(e=>`<div class="event"><small>${esc(e.time)}</small><h3>${esc(e.title)}</h3><p>${esc(e.notes)}</p></div>`).join('')}</div>`}function roadmap(){return [['M-01','Observable execution',100],['M-02','Traceable evolution',100],['M-03','Cross-project imports',64],['M-04','Self-directed coordination',20]].map(([id,t,n])=>`<div class="road"><div class="road-top"><span><span class="id">${id}</span> &nbsp; ${t}</span><span>${n}%</span></div><div class="bar"><i style="width:${n}%"></i></div></div>`).join('')}
function render(){view=location.hash.slice(1)||'overview';if(!views.some(x=>x[0]===view))view='overview';$('#nav').innerHTML=views.map(([v,i,t])=>`<a href="#${v}" class="${v===view?'active':''}"><span>${i}</span>${t}${v==='merges'?`<em>${3-Object.keys(state.decisions).length}</em>`:''}</a>`).join('');$('#crumb').textContent=views.find(x=>x[0]===view)[2];$('#heading').textContent=({overview:'System overview',merges:'Merge workbench',history:'Decision → evolution',agents:'Roles & responsibilities'})[view]||views.find(x=>x[0]===view)[2];$('#subtitle').textContent=({overview:'A clear view of what’s evolving. And why.',merges:'Different codebases. Explicit choices. Traceable outcomes.',history:'Follow the reasoning through implementation and evaluation.',signals:'Derived observations from system activity — evidence for review.'})[view]||'Structured context for the evolving system.';
let html='';if(view==='overview')html=`<div class="stats">${[['Current cycle','024','Awaiting file-level decisions','↻'],['Open tickets',state.tickets.filter(t=>t[2]!=='Implemented').length,'1 in progress · 1 in review','▤'],['Import conflicts',3-Object.keys(state.decisions).length,'apples → peaches · 2 versions','⑂'],['Latest evaluation','42 / 42','Example integration checks passed','✓']].map(([l,n,s,i])=>`<div class="stat"><span class="icon">${i}</span><div class="label">${l}</div><strong>${n}</strong><small>${s}</small></div>`).join('')}</div><div class="grid">${panel('Current evolution cycle',`<div class="pad"><div class="cycle-meta"><div><h3>Cycle 024 <span style="color:#7a8970">/ Cross-project import</span></h3><p style="font-size:11px">External loop orchestrates · local LLM implements</p></div>${badge(state.phase,'amber')}</div><div class="steps">${['Observe','Plan','Resolve','Implement','Evaluate'].map((s,i)=>`<div class="step ${i>2?'pending':''}"><b>${i<2?'✓':i+1}</b>${s}</div>`).join('')}</div><div class="notice">${3-Object.keys(state.decisions).length} file decisions remaining. Accepted decisions inform the next evolution step; implementation and evaluation are recorded separately.</div></div>`,goLink('merges','Resolve conflicts'))}${panel('Roadmap progress',roadmap(),goLink('roadmap','View roadmap'))}</div><div class="grid">${panel('Recent evolution',events(),goLink('history','Full history'))}${panel('Coordination signals',`<div class="row"><div><h3>Import boundary pressure</h3><small>3 incompatible contracts · derived</small></div>${badge('Review','amber')}</div><div class="row"><div><h3>Evaluation stability</h3><small>Latest example run · 42 / 42 passed</small></div>${badge('Stable')}</div><div class="row"><div><h3>Decision coverage</h3><small>${Object.keys(state.decisions).length} of 3 file decisions recorded</small></div>${badge('Observed','blue')}</div><div class="pad"><p style="font-size:11px">Signals summarize underlying evidence. They do not autonomously steer the loop.</p></div>`,goLink('signals','Inspect signals'))}</div>`;
if(view==='roadmap')html=panel('Evolution roadmap · example milestones',roadmap())+`<div class="grid">${panel('M-03 · Cross-project imports','<div class="pad"><h3>Apples into peaches</h3><p>Imports can combine unrelated architectures. Track semantic, lifecycle, and configuration differences at file level before evolving the combined system.</p><br>'+goLink('tickets','Inspect linked tickets')+'</div>')}${panel('Next milestone','<div class="pad"><h3>M-04 · Self-directed coordination</h3><p>Proposed: use evaluated outcomes to inform future ticket generation, with explicit roles and a reviewable decision trail.</p></div>')}</div>`;
if(view==='tickets'||view==='changes'){const tickets=view==='tickets',rows=tickets?state.tickets:state.changes;html=`<div class="toolbar"><input id="search" placeholder="Search ${view}…" aria-label="Search records"><select id="filter" aria-label="Status filter"><option>All statuses</option>${['Proposed','In progress','Merge review','Implemented'].map(x=>`<option>${x}</option>`).join('')}</select></div><section class="panel"><table><thead><tr>${(tickets?['ID / TICKET','STATUS','OWNER','MILESTONE']:['ID / CHANGE','STATUS','SOURCE TICKET']).map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody id="rows">${rows.map(r=>`<tr data-search="${esc(r.join(' ').toLowerCase())}" data-status="${r[2]}"><td><small>${r[0]}</small>${esc(r[1])}</td><td>${badge(r[2],r[2]==='Implemented'?'':'amber')}</td>${r.slice(3).map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></section><div class="context" style="margin-top:20px">AB-112 → per-file decision → proposed CH-027 → implementation record → evaluation.</div>`}
if(view==='agents')html=`<div class="role-grid">${[['01','External loop','Orchestration','Maintains roadmap context, generates tickets, evaluates runs, and proposes the next architectural evolution.'],['02','Local LLM','Implementation','Works on assigned tickets, proposes file-level merge strategies, and implements accepted changes in Java / Spring Boot.'],['03','Human reviewer','Decision authority','Compares alternatives, records rationale, and resolves ambiguous domain or architecture choices.']].map(([n,t,b,p])=>`<section class="panel"><div class="role-icon">${n}</div><h2>${t}</h2><br>${badge(b)}<p>${p}</p></section>`).join('')}</div><div class="context" style="margin-top:24px">Role definitions describe the intended workflow. No agents are connected to this workspace.</div>`;
if(view==='merges'){let f=files[selected],d=state.decisions[selected];html=`<div class="context">IMPORT IMP-024 &nbsp; / &nbsp; apples v2 → peaches v5 &nbsp; / &nbsp; Example heterogeneous import</div><div class="merge-layout"><section class="panel"><div class="panel-head"><h2>Conflicting files</h2>${badge('3 files','amber')}</div>${files.map((f,i)=>`<button class="file ${i===selected?'selected':''}" data-file="${i}">${esc(f.name)}<small>${state.decisions[i]?'Decision recorded':f.kind}</small></button>`).join('')}</section><section class="panel"><div class="panel-head"><h2>${f.name}</h2>${badge(d?'Decided':'Needs decision',d?'':'amber')}</div><div class="pad"><small>${f.path} · AB-112</small><div class="options"><div class="option"><h3>Target · peaches v5</h3><pre>${esc(f.a)}</pre></div><div class="option"><h3>Imported · apples v2</h3><pre>${esc(f.b)}</pre></div></div><div class="subhead"><h2>Compare merge strategies</h2><span class="link">Illustrative proposals</span></div><div class="options">${f.options.map(([t,p,r],i)=>`<div class="option"><small>OPTION ${i+1}</small><h3>${t}</h3><p>${p}</p><small>${r}</small><br><button data-decide="${i}">${d?.option===t?'✓ Selected strategy':'Record this decision'}</button></div>`).join('')}</div>${d?`<div class="decision-note">Decision: ${esc(d.option)}<p>${esc(d.rationale)}</p><small>${esc(d.time)} · awaiting implementation evidence</small></div>`:''}<div class="subhead"><h2>LLM consultation notebook</h2><button id="proposal">＋ Record LLM option</button></div><p style="font-size:12px">Suggested prompt: Compare both contracts, identify semantic risks, and propose a file-level merge with validation steps. Paste an LLM response below to preserve its provenance. No model is connected.</p>${(state.proposals[selected]||[]).map(p=>`<div class="option" style="margin-top:14px"><small>RECORDED LLM PROPOSAL · ${esc(p.time)}</small><h3>${esc(p.title)}</h3><p style="white-space:pre-wrap">${esc(p.notes)}</p><button data-custom="${esc(p.title)}">Record decision for this option</button></div>`).join('')}</div></section></div>`}
if(view==='history')html=panel('Trace ledger · newest first',events())+`<div class="pad">${goLink('changes','Inspect proposed and implemented changes')}</div>`;
if(view==='evaluations')html=panel('Evaluation evidence',`<div class="row"><div><small>E-017 · CYCLE 023 · EXAMPLE</small><h3>Import adapter regression</h3><p>Decision D-008 → AB-108 → CH-024 → E-017</p></div>${badge('Passed · 42 / 42')}</div><div class="pad"><p>Scope: example integration checks for isolated adapters. This sample result is not evidence from your repository.</p></div><div class="row"><div><small>E-018 · CYCLE 024</small><h3>Cross-project compatibility</h3><p>Pending implementation and an actual evaluation run.</p></div>${badge('Not run','amber')}</div>`);
if(view==='signals')html=panel('Derived observations',`<div class="row"><div><h3>Decision coverage</h3><p>Source: recorded decisions for IMP-024.</p></div><strong>${Object.keys(state.decisions).length} / 3</strong></div><div class="row"><div><h3>Open contract mismatches</h3><p>Source: lifecycle, configuration, and capability differences.</p></div>${badge(String(3-Object.keys(state.decisions).length),'amber')}</div><div class="row"><div><h3>Last evaluated outcome</h3><p>Source: E-017, example cycle 023.</p></div>${badge('42 / 42')}</div><div class="pad"><p>Signals are summaries derived from events, decisions, and evaluation evidence. Review the underlying records before choosing the next step.</p></div>`);
$('#app').innerHTML=html;document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>{selected=+b.dataset.file;render()});document.querySelectorAll('[data-decide]').forEach(b=>b.onclick=()=>openModal('decision',fOption(+b.dataset.decide)));document.querySelectorAll('[data-custom]').forEach(b=>b.onclick=()=>openModal('decision',b.dataset.custom));if($('#proposal'))$('#proposal').onclick=()=>openModal('proposal');if($('#search')){const filter=()=>document.querySelectorAll('#rows tr').forEach(r=>r.hidden=!r.dataset.search.includes($('#search').value.toLowerCase())||($('#filter').value!=='All statuses'&&r.dataset.status!==$('#filter').value));$('#search').oninput=filter;$('#filter').onchange=filter}}
function fOption(i){return files[selected].options[i][0]}function openModal(mode,title=''){modalMode=mode;$('#modalTitle').textContent=mode==='decision'?'Record merge decision':mode==='proposal'?'Record LLM-proposed option':'Record evolution event';$('#recordTitle').value=title;$('#recordNotes').value='';$('#dialog').showModal()}
$('#new').onclick=()=>openModal('event');$('#dialog form').addEventListener('submit',e=>{if(e.submitter.value!=='save')return;let title=$('#recordTitle').value.trim(),notes=$('#recordNotes').value.trim();if(!title||!notes){e.preventDefault();return}let time=new Date().toLocaleString();if(modalMode==='proposal'){(state.proposals[selected]??=[]).push({title,notes,time});state.events.unshift({title:`LLM option recorded · ${files[selected].name}`,notes:title+' · '+notes,time})}else if(modalMode==='decision'){state.decisions[selected]={option:title,rationale:notes,time};state.events.unshift({title:`Decision · ${files[selected].name}`,notes:`IMP-024 → AB-112 → ${title}. Rationale: ${notes}. Implementation and evaluation pending.`,time});if(Object.keys(state.decisions).length===3)state.phase='Ready for implementation'}else state.events.unshift({title,notes,time});persist();render()});$('#export').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='autobuilder-workspace.json';a.click();URL.revokeObjectURL(a.href)};$('#import').onclick=()=>$('#upload').click();$('#upload').onchange=async e=>{try{let s=JSON.parse(await e.target.files[0].text());if(!Array.isArray(s.events)||!Array.isArray(s.tickets)||!Array.isArray(s.changes)||typeof s.decisions!=='object'||typeof s.proposals!=='object')throw Error();state=s;persist();render()}catch{alert('Import a valid Autobuilder workspace JSON export.')}e.target.value=''};window.onhashchange=render;render();
